description:
Turn lesson 5.03's checklist into an audit of a driver's description:

```cpp
struct IoctlSpec { std::string name; int method; int access; bool changesState; bool checksLengths; bool returnsPointers; bool takesAddress; };
struct DriverSpec { bool secureDevice; bool secureOpen; bool zeroesOutput; std::vector<IoctlSpec> ioctls; };

std::vector<std::string> audit(const DriverSpec& d);
```

Findings, in this order (driver-wide first, then for each IOCTL in order, its findings in the order listed):
- `"device can be opened by anyone"` if not `secureDevice`;
- `"opens below the device skip the security check"` if not `secureOpen`;
- `"output buffers are not zeroed"` if not `zeroesOutput`;
- for each IOCTL, prefixed with `"<name>: "`:
  - `"METHOD_NEITHER"` if `method == 3`;
  - `"changes state without write access"` if `changesState` and the access lacks bit 1 (`FILE_WRITE_DATA` is 2);
  - `"lengths not checked"` if not `checksLengths`;
  - `"returns kernel pointers"` if `returnsPointers`;
  - `"accepts an address to access"` if `takesAddress`.

starter.solution.cpp:
#include <string>
#include <vector>

struct IoctlSpec { std::string name; int method; int access; bool changesState; bool checksLengths; bool returnsPointers; bool takesAddress; };
struct DriverSpec { bool secureDevice; bool secureOpen; bool zeroesOutput; std::vector<IoctlSpec> ioctls; };

std::vector<std::string> audit(const DriverSpec& d) { return { "?" }; }

solution.solution.cpp:
#include <string>
#include <vector>

struct IoctlSpec { std::string name; int method; int access; bool changesState; bool checksLengths; bool returnsPointers; bool takesAddress; };
struct DriverSpec { bool secureDevice; bool secureOpen; bool zeroesOutput; std::vector<IoctlSpec> ioctls; };

std::vector<std::string> audit(const DriverSpec& d)
{
    std::vector<std::string> f;
    if (!d.secureDevice) f.push_back("device can be opened by anyone");
    if (!d.secureOpen) f.push_back("opens below the device skip the security check");
    if (!d.zeroesOutput) f.push_back("output buffers are not zeroed");
    for (const IoctlSpec& i : d.ioctls)
    {
        const std::string p{ i.name + ": " };
        if (i.method == 3) f.push_back(p + "METHOD_NEITHER");
        if (i.changesState && !(i.access & 2)) f.push_back(p + "changes state without write access");
        if (!i.checksLengths) f.push_back(p + "lengths not checked");
        if (i.returnsPointers) f.push_back(p + "returns kernel pointers");
        if (i.takesAddress) f.push_back(p + "accepts an address to access");
    }
    return f;
}

unitTests:
using Findings = std::vector<std::string>;
TEST("the log driver is clean") {
    const DriverSpec log{ true, true, true, { { "LOG_READ", 0, 1, false, true, false, false } } };
    CHECK(audit(log).empty());
}
TEST("a worrying driver") {
    const DriverSpec bad{ false, true, false, {
        { "RESET", 0, 0, true, true, false, false },
        { "PEEK", 3, 3, false, false, true, true },
        { "STATS", 0, 1, false, true, false, false } } };
    CHECK_EQ(audit(bad), (Findings{ "device can be opened by anyone", "output buffers are not zeroed", "RESET: changes state without write access",
                                    "PEEK: METHOD_NEITHER", "PEEK: lengths not checked", "PEEK: returns kernel pointers", "PEEK: accepts an address to access" }));
}
TEST("write access fixes the state finding") { const DriverSpec d{ true, false, true, { { "SET", 0, 2, true, true, false, false }, { "SET2", 0, 3, true, true, false, false } } }; CHECK_EQ(audit(d), (Findings{ "opens below the device skip the security check" })); }

